EXPORTED void freeentryatts(struct entryattlist *l) /* <=== freeentryatts */ 
{
    struct entryattlist *n;

    while (l) {
        n = l->next;
        free(l->entry);
        freeattvalues(l->attvalues);
        free(l);
        l = n;
    }
}

EXPORTED size_t strlcpy(char *dst, const char *src, size_t len) /* <=== strlcpy */ 
{
    size_t n;

    if (len <= 0) {
        /* we can't do anything ! */
        return strlen(src);
    }

    /* assert(len >= 1); */
    for (n = 0; n < len-1; n++) {
        if ((dst[n] = src[n]) == '\0') break;
    }
    if (n >= len-1) {
        /* ran out of space */
        dst[n] = '\0';
        while(src[n]) n++;
    }
    return n;
}

EXPORTED int cyrusdb_forone(struct db *db, /* <=== cyrusdb_forone */ 
               const char *key, size_t keylen,
               foreach_p *p,
               foreach_cb *cb, void *rock,
               struct txn **tid)
{
    const char *data;
    size_t datalen;
    int r = cyrusdb_fetch(db, key, keylen, &data, &datalen, tid);
    if (r == CYRUSDB_NOTFOUND) return 0;
    if (r) return r;

    if (!p || p(rock, key, keylen, data, datalen))
        r = cb(rock, key, keylen, data, datalen);
    return r;
}

EXPORTED int strarray_size(const strarray_t *sa) /* <=== strarray_size */ 
{
    return sa->count;
}

EXPORTED void* xmalloc(size_t size) /* <=== xmalloc */ 
{
    void *ret;

    ret = malloc(size);
    if (ret != NULL) return ret;

    fatal("Virtual memory exhausted", EC_TEMPFAIL);
    return 0; /*NOTREACHED*/
}

EXPORTED void proc_cleanup(void) /* <=== proc_cleanup */ 
{
    if (procfname) {
        unlink(procfname);
        free(procfname);
        procfname = NULL;
    }
}

